"""Extra independent, offline boundary checks."""
SNIPPETS = ['def add(value, items=None):\n    if items is None:\n        items = []\n    items.append(value)\n    return items\nassert add(2) == [2] and add(3) == [3]', "text = '冰水'\nwire = text.encode('utf-8')\nassert (len(text), len(wire), wire.decode('utf-8')) == (2, 6, text)", 'def configured(value, fallback):\n    return fallback if value is None else value\nassert configured(0, 100) == 0\nassert configured(None, 100) == 100', "points = [['T01', 24], ['T02', 26]]\ncopy = points[:]\ncopy[0][1] = 25\nassert copy is not points and points[0][1] == 25", "def find_alarm(points):\n    for name, value in points:\n        if value >= 30:\n            break\n    else:\n        return None\n    return name\nassert find_alarm([('T01', 20)]) is None\nassert find_alarm([('T02', 31)]) == 'T02'", "def samples(n: int) -> int:\n    if type(n) is not int or n < 0:\n        raise ValueError('invalid sample count')\n    return n\nassert samples(0) == 0\ntry:\n    samples(True)\nexcept ValueError:\n    pass\nelse:\n    raise AssertionError('accepted boolean')", 'broken = [lambda: n for n in range(3)]\nfixed = [lambda n=n: n for n in range(3)]\nassert [f() for f in broken] == [2, 2, 2]\nassert [f() for f in fixed] == [0, 1, 2]', 'from dataclasses import dataclass, field\n@dataclass\nclass Batch:\n    values: list[int] = field(default_factory=list)\na, b = Batch(), Batch()\na.values.append(2)\nassert b.values == []', 'rows = iter([10, 20])\nassert sum(rows) == 30\nassert list(rows) == []', "from contextlib import contextmanager\nstate = []\n@contextmanager\ndef resource():\n    try:\n        yield\n    finally:\n        state.append('closed')\ntry:\n    with resource():\n        raise OSError('simulated')\nexcept OSError:\n    assert state == ['closed']"]

if __name__ == "__main__":
    for i, source in enumerate(SNIPPETS, 1):
        exec(compile(source, f"<boundary-{i}>", "exec"), {})
        print(f"boundary {i:02d}: OK")
